/* ========== RESET & BASE ========== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: 'DM Sans', sans-serif;
  color: var(--text-primary);
  background: var(--bg-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

/* ========== CUSTOM PROPERTIES ========== */
:root {
  --green-primary: #00824A;
  --green-dark: #006838;
  --green-light: #E8F5EE;
  --forest: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FBF5E8;
  --cream-dark: #E8C477;
  --bg-primary: #FFFFFF;
  --bg-warm: #FAFAF5;
  --bg-cream: #FDF8EF;
  --text-primary: #1E1E1E;
  --text-secondary: #5C5C5C;
  --text-tertiary: #8A8A8A;
  --border-color: #E5E5E0;
  --border-light: #F0F0EB;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --header-height: 72px;
  --max-width: 1280px;
  --transition: 0.25s ease;
}

/* ========== TYPOGRAPHY ========== */
h1, h2, h3, h4 { font-family: 'Playfair Display', serif; font-weight: 700; line-height: 1.15; }
h1 { font-size: 3rem; }
h2 { font-size: 2.25rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }
p { color: var(--text-secondary); }
.section-label {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--green-primary);
  margin-bottom: 0.5rem;
}

/* ========== LAYOUT ========== */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--cream { background: var(--bg-cream); }
.section--green { background: var(--green-primary); color: #fff; }
.section--green p { color: rgba(255,255,255,0.85); }
.section--warm { background: var(--bg-warm); }

/* ========== BUTTONS ========== */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full);
  font-weight: 600; font-size: 0.95rem;
  transition: all var(--transition);
  text-align: center; justify-content: center;
}
.btn--primary { background: var(--green-primary); color: #fff; }
.btn--primary:hover { background: var(--green-dark); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--outline { background: transparent; color: var(--green-primary); border: 2px solid var(--green-primary); }
.btn--outline:hover { background: var(--green-primary); color: #fff; }
.btn--white { background: #fff; color: var(--green-primary); }
.btn--white:hover { background: var(--cream-light); transform: translateY(-1px); }
.btn--cream { background: var(--cream); color: var(--forest); }
.btn--cream:hover { background: var(--cream-dark); }
.btn--sm { padding: 8px 20px; font-size: 0.85rem; }
.btn--lg { padding: 16px 36px; font-size: 1.05rem; }

/* ========== HEADER ========== */
.header {
  position: sticky; top: 0; z-index: 100;
  background: #fff; height: var(--header-height);
  border-bottom: 1px solid var(--border-color);
  display: flex; align-items: center;
}
.header__inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
  display: flex; align-items: center; width: 100%;
}
.header__logo {
  display: flex; align-items: center; gap: 10px;
  font-family: 'Playfair Display', serif; font-weight: 700;
  font-size: 1.35rem; color: var(--green-primary);
  flex-shrink: 0;
}
.header__logo i { font-size: 1.6rem; }
.header__nav { display: flex; align-items: center; gap: 32px; margin-left: 48px; }
.header__nav a {
  font-weight: 600; font-size: 0.95rem; color: var(--text-primary);
  transition: color var(--transition); position: relative;
}
.header__nav a:hover { color: var(--green-primary); }
.header__nav a::after {
  content: ''; position: absolute; bottom: -4px; left: 0; width: 0;
  height: 2px; background: var(--green-primary); transition: width var(--transition);
}
.header__nav a:hover::after { width: 100%; }
.header__actions { margin-left: auto; display: flex; align-items: center; gap: 16px; }
.header__actions .btn { padding: 8px 20px; font-size: 0.85rem; }
.header__hamburger { display: none; font-size: 1.5rem; color: var(--text-primary); padding: 8px; }

/* ========== MOBILE NAV ========== */
.mobile-nav {
  display: none; position: fixed; top: var(--header-height); left: 0; right: 0; bottom: 0;
  background: #fff; z-index: 99; padding: 24px;
  flex-direction: column; gap: 8px;
  animation: slideDown 0.3s ease;
}
.mobile-nav.active { display: flex; }
.mobile-nav a {
  display: block; padding: 14px 0; font-size: 1.1rem; font-weight: 600;
  color: var(--text-primary); border-bottom: 1px solid var(--border-light);
}
.mobile-nav a:hover { color: var(--green-primary); }
.mobile-nav__actions { margin-top: 24px; display: flex; flex-direction: column; gap: 12px; }
@keyframes slideDown { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }

/* ========== FOOTER ========== */
.footer { background: var(--forest); color: #fff; padding: 64px 0 32px; }
.footer__grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
}
.footer__col h4 {
  font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 700;
  margin-bottom: 16px; color: #fff;
}
.footer__col a {
  display: block; font-size: 0.875rem; color: rgba(255,255,255,0.7);
  padding: 4px 0; transition: color var(--transition);
}
.footer__col a:hover { color: #fff; }
.footer__bottom {
  max-width: var(--max-width); margin: 0 auto; padding: 32px 24px 0;
  border-top: 1px solid rgba(255,255,255,0.15); margin-top: 48px;
  display: flex; align-items: center; justify-content: space-between;
}
.footer__social { display: flex; gap: 16px; }
.footer__social a { color: rgba(255,255,255,0.7); font-size: 1.25rem; transition: color var(--transition); }
.footer__social a:hover { color: #fff; }
.footer__copy { font-size: 0.8rem; color: rgba(255,255,255,0.5); }

/* Footer accordion for mobile */
.footer__accordion-btn {
  display: none; width: 100%; justify-content: space-between; align-items: center;
  padding: 14px 0; border-bottom: 1px solid rgba(255,255,255,0.1);
  font-size: 0.95rem; font-weight: 700; color: #fff; text-align: left;
}
.footer__accordion-btn i { transition: transform var(--transition); font-size: 1.1rem; }
.footer__accordion-btn.open i { transform: rotate(180deg); }
.footer__accordion-content { overflow: hidden; transition: max-height 0.3s ease; }
.footer__accordion-content a { display: block; font-size: 0.875rem; color: rgba(255,255,255,0.7); padding: 4px 0; }

/* ========== COOKIE BANNER ========== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--forest); color: #fff; padding: 20px 24px;
  display: flex; align-items: center; gap: 24px;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
}
.cookie-banner.hidden { display: none; }
.cookie-banner__text { flex: 1; }
.cookie-banner__text h4 {
  font-family: 'DM Sans', sans-serif; font-size: 0.95rem; font-weight: 700;
  margin-bottom: 4px;
}
.cookie-banner__text p { font-size: 0.85rem; color: rgba(255,255,255,0.75); }
.cookie-banner__actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ========== HERO ========== */
.hero {
  position: relative; overflow: hidden;
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  color: #fff; padding: 100px 0 80px;
  min-height: 520px; display: flex; align-items: center;
}
.hero__inner { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; width: 100%; position: relative; z-index: 2; }
.hero h1 { color: #fff; max-width: 600px; margin-bottom: 20px; }
.hero p { color: rgba(255,255,255,0.85); font-size: 1.15rem; max-width: 480px; margin-bottom: 32px; }
.hero__deco {
  position: absolute; right: -40px; top: 50%; transform: translateY(-50%);
  width: 420px; height: 420px; border-radius: 50%;
  background: rgba(255,255,255,0.06); z-index: 1;
}
.hero__deco::after {
  content: ''; position: absolute; right: 40px; top: 40px;
  width: 340px; height: 340px; border-radius: 50%;
  background: rgba(255,255,255,0.05);
}

/* ========== PROMO CARDS ========== */
.promo-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 24px;
}
.promo-card {
  background: var(--bg-cream); border-radius: var(--radius-lg);
  overflow: hidden; transition: transform var(--transition), box-shadow var(--transition);
}
.promo-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.promo-card__img {
  height: 240px; background: linear-gradient(135deg, var(--green-light), var(--cream-light));
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem; color: var(--green-primary);
}
.promo-card__body { padding: 28px; }
.promo-card__body h3 { margin-bottom: 10px; }
.promo-card__body p { margin-bottom: 20px; font-size: 0.95rem; }

/* ========== SEASONAL HIGHLIGHT ========== */
.seasonal {
  display: grid; grid-template-columns: 1fr 1fr; gap: 0;
  border-radius: var(--radius-xl); overflow: hidden;
  box-shadow: var(--shadow-md);
}
.seasonal--reverse .seasonal__content { order: 2; }
.seasonal--reverse .seasonal__img { order: 1; }
.seasonal__content { padding: 56px; display: flex; flex-direction: column; justify-content: center; }
.seasonal__content h2 { margin-bottom: 16px; }
.seasonal__content p { margin-bottom: 28px; font-size: 1.05rem; }
.seasonal__img {
  min-height: 400px;
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
}
.seasonal__img--fruity { background: linear-gradient(135deg, #FFE0B2, #FFCC80); color: #E65100; }
.seasonal__img--spring { background: linear-gradient(135deg, #E1BEE7, #CE93D8); color: #6A1B9A; }

/* ========== REWARDS HERO ========== */
.rewards-hero {
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  text-align: center; padding: 80px 0;
}
.rewards-hero h1 { margin-bottom: 16px; }
.rewards-hero p { max-width: 560px; margin: 0 auto 28px; font-size: 1.1rem; }

/* ========== HOW IT WORKS ========== */
.steps-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px;
  text-align: center; counter-reset: step;
}
.step { position: relative; }
.step__number {
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--green-primary); color: #fff;
  font-size: 1.25rem; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px;
}
.step h3 { margin-bottom: 10px; }
.step p { font-size: 0.95rem; }

/* ========== STATUS TIERS ========== */
.tiers-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
}
.tier-card {
  border-radius: var(--radius-lg); padding: 32px; text-align: center;
  border: 2px solid var(--border-color); transition: all var(--transition);
}
.tier-card:hover { border-color: var(--green-primary); transform: translateY(-2px); }
.tier-card--gold { border-color: var(--cream-dark); background: var(--cream-light); }
.tier-card--reserve { border-color: var(--green-primary); background: var(--green-light); }
.tier-card__icon { font-size: 2.5rem; margin-bottom: 16px; }
.tier-card h3 { margin-bottom: 6px; }
.tier-card__threshold { font-size: 0.9rem; color: var(--text-tertiary); margin-bottom: 16px; }
.tier-card__benefits { text-align: left; }
.tier-card__benefits li {
  font-size: 0.9rem; color: var(--text-secondary); padding: 6px 0;
  padding-left: 20px; position: relative;
}
.tier-card__benefits li::before {
  content: '\EB7B'; font-family: 'remixicon'; position: absolute; left: 0;
  color: var(--green-primary); font-size: 0.85rem;
}

/* ========== REDEMPTION TABS ========== */
.redemption { background: var(--bg-cream); }
.redemption__tabs {
  display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 32px;
}
.redemption__tab {
  padding: 10px 24px; border-radius: var(--radius-full);
  font-weight: 600; font-size: 0.9rem;
  background: #fff; color: var(--text-secondary);
  border: 2px solid var(--border-color);
  transition: all var(--transition);
}
.redemption__tab:hover { border-color: var(--green-primary); color: var(--green-primary); }
.redemption__tab.active {
  background: var(--green-primary); color: #fff; border-color: var(--green-primary);
}
.redemption__panel {
  background: #fff; border-radius: var(--radius-lg); padding: 40px;
  box-shadow: var(--shadow-sm);
  display: none;
}
.redemption__panel.active { display: flex; align-items: center; gap: 40px; }
.redemption__panel-icon {
  width: 120px; height: 120px; border-radius: var(--radius-md);
  background: var(--green-light); display: flex; align-items: center; justify-content: center;
  font-size: 3rem; flex-shrink: 0;
}
.redemption__panel-content h3 { margin-bottom: 8px; }
.redemption__panel-value {
  display: inline-block; background: var(--cream); color: var(--forest);
  padding: 4px 14px; border-radius: var(--radius-full);
  font-weight: 700; font-size: 0.85rem; margin-bottom: 12px;
}

/* ========== PARTNERSHIPS ========== */
.partners-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 24px;
}
.partner-card {
  display: flex; align-items: center; gap: 24px;
  background: #fff; border-radius: var(--radius-lg); padding: 28px;
  border: 1px solid var(--border-color); transition: all var(--transition);
}
.partner-card:hover { box-shadow: var(--shadow-md); transform: translateY(-1px); }
.partner-card__icon {
  width: 64px; height: 64px; border-radius: var(--radius-md);
  background: var(--bg-cream); display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; color: var(--green-primary); flex-shrink: 0;
}
.partner-card h4 { margin-bottom: 4px; }

/* ========== APP DOWNLOAD ========== */
.app-cta {
  text-align: center; padding: 64px 0;
  background: linear-gradient(135deg, var(--green-primary), var(--green-dark));
  color: #fff; border-radius: var(--radius-xl);
}
.app-cta h2 { color: #fff; margin-bottom: 12px; }
.app-cta p { color: rgba(255,255,255,0.85); margin-bottom: 28px; }

/* ========== MENU PAGE ========== */
.menu-layout {
  display: grid; grid-template-columns: 260px 1fr; gap: 0;
  max-width: var(--max-width); margin: 0 auto;
}
.menu-sidebar {
  padding: 32px 24px; border-right: 1px solid var(--border-color);
  position: sticky; top: var(--header-height); height: calc(100vh - var(--header-height));
  overflow-y: auto;
}
.menu-sidebar__group { margin-bottom: 28px; }
.menu-sidebar__group-title {
  font-family: 'DM Sans', sans-serif; font-size: 0.75rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--text-tertiary); margin-bottom: 8px;
}
.menu-sidebar__group a {
  display: block; padding: 8px 12px; border-radius: var(--radius-sm);
  font-size: 0.9rem; color: var(--text-secondary); transition: all var(--transition);
}
.menu-sidebar__group a:hover { background: var(--green-light); color: var(--green-primary); }
.menu-sidebar__group a.active { background: var(--green-light); color: var(--green-primary); font-weight: 600; }
.menu-main { padding: 32px 40px; }
.menu-section { margin-bottom: 48px; }
.menu-section h2 { margin-bottom: 20px; padding-bottom: 12px; border-bottom: 2px solid var(--border-light); }
.menu-items {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 20px;
}
.menu-item {
  background: #fff; border-radius: var(--radius-md); padding: 20px;
  border: 1px solid var(--border-light); text-align: center;
  transition: all var(--transition);
}
.menu-item:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.menu-item__icon {
  width: 80px; height: 80px; border-radius: 50%;
  background: var(--bg-cream); margin: 0 auto 14px;
  display: flex; align-items: center; justify-content: center;
  font-size: 2rem; color: var(--green-primary);
}
.menu-item h4 { font-family: 'DM Sans', sans-serif; font-size: 0.95rem; margin-bottom: 4px; }
.menu-item p { font-size: 0.8rem; }

/* ========== BREADCRUMB ========== */
.breadcrumb {
  padding: 16px 0; font-size: 0.85rem; color: var(--text-tertiary);
  max-width: var(--max-width); margin: 0 auto;
}
.breadcrumb a { color: var(--text-tertiary); transition: color var(--transition); }
.breadcrumb a:hover { color: var(--green-primary); }
.breadcrumb span { margin: 0 8px; }

/* ========== GIFT PAGE ========== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  text-align: center; padding: 80px 0;
}
.gift-hero h1 { margin-bottom: 12px; }
.gift-hero p { max-width: 520px; margin: 0 auto 28px; font-size: 1.1rem; }

/* Carousel */
.carousel { position: relative; margin-bottom: 56px; }
.carousel__header {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px;
}
.carousel__header h3 { font-family: 'Playfair Display', serif; }
.carousel__nav { display: flex; gap: 8px; }
.carousel__nav button {
  width: 40px; height: 40px; border-radius: 50%;
  border: 2px solid var(--border-color); background: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; color: var(--text-secondary);
  transition: all var(--transition);
}
.carousel__nav button:hover { border-color: var(--green-primary); color: var(--green-primary); }
.carousel__track-wrapper { overflow: hidden; border-radius: var(--radius-md); }
.carousel__track {
  display: flex; gap: 16px; transition: transform 0.4s ease;
}
.carousel__card {
  min-width: 180px; flex-shrink: 0;
  background: #fff; border-radius: var(--radius-md);
  border: 1px solid var(--border-light); overflow: hidden;
  transition: all var(--transition); cursor: pointer;
}
.carousel__card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.carousel__card-img {
  height: 120px; display: flex; align-items: center; justify-content: center;
  font-size: 2.5rem;
}
.carousel__card-img--green { background: linear-gradient(135deg, var(--green-light), #C8E6C9); color: var(--green-primary); }
.carousel__card-img--pink { background: linear-gradient(135deg, #FCE4EC, #F8BBD0); color: #C2185B; }
.carousel__card-img--gold { background: linear-gradient(135deg, var(--cream-light), var(--cream)); color: var(--forest); }
.carousel__card-img--blue { background: linear-gradient(135deg, #E3F2FD, #BBDEFB); color: #1565C0; }
.carousel__card-img--purple { background: linear-gradient(135deg, #F3E5F5, #E1BEE7); color: #7B1FA2; }
.carousel__card-img--orange { background: linear-gradient(135deg, #FFF3E0, #FFE0B2); color: #E65100; }
.carousel__card-img--teal { background: linear-gradient(135deg, #E0F2F1, #B2DFDB); color: #00695C; }
.carousel__card-img--red { background: linear-gradient(135deg, #FFEBEE, #FFCDD2); color: #C62828; }
.carousel__card-name {
  padding: 12px; text-align: center; font-size: 0.85rem; font-weight: 600;
}

/* ========== BUSINESS GIFTING ========== */
.business-gifting {
  display: flex; align-items: center; gap: 48px;
  background: var(--bg-cream); border-radius: var(--radius-xl); padding: 48px;
}
.business-gifting__content { flex: 1; }
.business-gifting__content h2 { margin-bottom: 12px; }
.business-gifting__content p { margin-bottom: 24px; }
.business-gifting__icon {
  width: 160px; height: 160px; border-radius: var(--radius-lg);
  background: var(--cream); display: flex; align-items: center; justify-content: center;
  font-size: 4rem; color: var(--forest); flex-shrink: 0;
}

/* ========== EGIFT INFO ========== */
.egift-info {
  background: #fff; border-radius: var(--radius-lg); padding: 40px;
  border: 1px solid var(--border-color);
}
.egift-info h3 { margin-bottom: 16px; }
.egift-info p { margin-bottom: 12px; font-size: 0.95rem; }
.egift-links { display: flex; gap: 24px; flex-wrap: wrap; margin-top: 16px; }
.egift-links a {
  color: var(--green-primary); font-weight: 600; font-size: 0.95rem;
  transition: opacity var(--transition);
}
.egift-links a:hover { opacity: 0.8; }

/* ========== FAQ ========== */
.faq-item {
  border-bottom: 1px solid var(--border-light);
}
.faq-item__btn {
  width: 100%; padding: 20px 0; display: flex; justify-content: space-between;
  align-items: center; text-align: left; font-weight: 600; font-size: 1rem;
  color: var(--text-primary);
}
.faq-item__btn i { font-size: 1.2rem; transition: transform var(--transition); flex-shrink: 0; }
.faq-item__btn.open i { transform: rotate(45deg); }
.faq-item__answer {
  max-height: 0; overflow: hidden; transition: max-height 0.3s ease;
}
.faq-item__answer p { padding-bottom: 20px; font-size: 0.95rem; }

/* ========== STORE LOCATOR ========== */
.locator-controls {
  background: #fff; padding: 24px 0; border-bottom: 1px solid var(--border-color);
}
.locator-controls__inner {
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
